return f'"{tokens_attr}"::jsonb ->>\'{self.tokens.fieldname}\' ILIKE \'%%{self.tokens.singleterm}%%\''
else:
    return f'"{self.tokens.field[0]}" ILIKE \'%%{self.tokens.singleterm}%%\''
